CREATE TABLE Attendance (
    att_id      INT AUTO_INCREMENT PRIMARY KEY,
    reg_no      VARCHAR(20)  NOT NULL,
    c_code      VARCHAR(20)  NOT NULL,
    att_date    DATE         NOT NULL,
    week_no     TINYINT      NOT NULL,  -- 1-15
    session_type ENUM('Theory','Practical') NOT NULL,
    status      ENUM('Present','Absent','Medical') NOT NULL DEFAULT 'Absent',
    tec_id      INT,                    -- TO who updated
    FOREIGN KEY (reg_no)  REFERENCES Student(reg_no)
    ON DELETE CASCADE ON UPDATE CASCADE,
    FOREIGN KEY (c_code)  REFERENCES Course(c_code)
    ON DELETE CASCADE ON UPDATE CASCADE,
    FOREIGN KEY (tec_id)  REFERENCES Technical_Officer(tec_id)
    ON DELETE CASCADE ON UPDATE CASCADE);

-- ============================================================
-- ATTENDANCE DATA  |  15 Weeks  |  Based on Level 1 Sem 2 Timetable
-- ============================================================
-- Timetable:
--   Mon  : MGT1201 Theory (9-11) | ICT1202 Theory+Practical (1-3)
--   Tue  : ICT1201 Practical (9-12) | ICT1203 Theory (1-2) | ICT1204 Practical (3-4)
--   Wed  : MAT1201 Theory (9-10)
--   Thu  : ENG1201 Theory (9-10) | ICT1205 Theory (10-12) | ICT1204 Practical (1-3)
--   Fri  : ICT1206 Theory (8-10)
-- ============================================================

